spec.rawSql:
select time_bucket('1 week', start_at, 'Europe/Vienna') as time, sum(distance) as "Distance"
from data_vehicle_trips
where $__timeFilter(start_at) and distance >= ${min_km}
group by 1
order by 1;

select time_bucket('1 week', start_at, 'Europe/Vienna') as time, count(*) as "Trips"
from data_vehicle_trips
where $__timeFilter(start_at) and distance >= ${min_km}
group by 1
order by 1;

select distance as "Distance"
from data_vehicle_trips
where $__timeFilter(start_at) and distance >= ${min_km}
order by start_at;

select max(start_at) as time, sum(consumption) / sum(distance) * 100 as "Consumption"
from data_vehicle_trips
where $__timeFilter(start_at) and distance >= ${min_km} and consumption > 0;
